    int height = image->sy;
    int rowBytes = (width + 7) / 8;
    char* cleanName = (char*)malloc(strlen(file_name) + 1);
    char* p = cleanName;
    for (char* src = file_name; *src; ++src) {
        if (isalnum(*src) || *src == '_') {
