    gdIOCtxPrintf(out, "#define %s_height %d\n", cleanName, height);
    gdIOCtxPrintf(out, "static unsigned char %s_bits[] = {\n  ", cleanName);
    for (j = 0; j < height; ++j) {
        for (i = 0; i < rowBytes; ++i) {
            unsigned char byte = 0;
            int startBit = i * 8;
            int endBit = (i + 1) * 8;
            endBit = (endBit > width) ? width : endBit;
            for (int b = startBit; b < endBit; ++b) {
                int color = gdImageGetPixel(image, b, j);
                byte = (byte << 1) | (color == fg ? 1 : 0);
            }
            gdIOCtxPrintf(out, "0x%02X", byte);
