                gdIOCtxPrintf(out, ",");
            }
        }
        if (j != height - 1) {
            gdIOCtxPrintf(out, ",\n  ");
        } else {
            gdIOCtxPrintf(out, "\n};\n");
        }
    }

    free(cleanName);
}

