void generateXBM(gdImagePtr image, char* file_name, int fg, gdIOCtx* out) {
    int width = gdImageSX(image);
    int height = gdImageSY(image);
    int i, j;
    char* modifiedFileName = (char*)malloc(strlen(file_name) + 1);
    strcpy(modifiedFileName, file_name);
    for (i = 0; modifiedFileName[i]; i++) {
        if (!isalnum(modifiedFileName[i])) {
            modifiedFileName[i] = '_';
        }
    }

    char buffer[256];
    sprintf(buffer, "#define %s_width %d\n#define %s_height %d\nstatic unsigned char %s_bits[] = {\n  ", modifiedFileName, width, modifiedFileName, height, modifiedFileName);
    gdIOCtxPut(out, buffer, strlen(buffer));

    for (i = 0; i < height; i++) {
        int rowSize = (width + 7) / 8;
        unsigned char* row = (unsigned char*)malloc(rowSize);
        for (j = 0; j < rowSize; j++) {
            row[j] = 0;
        }

        for (j = 0; j < width; j++) {
            int pixel = gdImageGetPixel(image, j, height - i - 1);
            if (pixel == fg) {
                row[j / 8] |= (1 << (7 - (j % 8)));
            }
        }

        for (j = 0; j < rowSize; j++) {
            sprintf(buffer, "0x%02X, ", row[j]);
            gdIOCtxPut(out, buffer, strlen(buffer));
            if ((j + 1) % 8 == 0) {
                gdIOCtxPut(out, "\n  ", 2);
            }
        }
        free(row);
    }

    sprintf(buffer, "\n};\n");
    gdIOCtxPut(out, buffer, strlen(buffer));

    free(modifiedFileName);
}

